/* Shared localStorage cache + same-origin snapshot fallback, used by
 * publications.js/presentations.js/repos.js.
 *
 * load() tries, in order:
 *   1. localStorage cache, if under 10 minutes old — skips any network call.
 *   2. the live fetch the caller provides — on success, also refreshes the
 *      localStorage cache for next time.
 *   3. the localStorage cache again, even if stale, if the live fetch failed.
 *   4. a same-origin deploy-time snapshot (data/{name}.json, generated by
 *      tools/data-snapshot in deploy.yml) — for a visitor whose live fetch
 *      failed and who has no local cache at all yet (e.g. first visit).
 *   5. onError — only if every layer above failed or produced nothing.
 */
var DataCache = (function () {
  'use strict';

  var TTL_MS = 10 * 60 * 1000; // 10 minutes

  function readCache(key) {
    try {
      var raw = localStorage.getItem(key);
      return raw ? JSON.parse(raw) : null;
    } catch (e) {
      return null; // private-mode/quota/unavailable — just behave as if empty
    }
  }

  function writeCache(key, data) {
    try {
      localStorage.setItem(key, JSON.stringify({ data: data, fetchedAt: Date.now() }));
    } catch (e) {
      /* storage unavailable or full — caching is a nice-to-have, not fatal */
    }
  }

  function isFresh(entry) {
    return !!entry && (Date.now() - entry.fetchedAt) < TTL_MS;
  }

  function fetchSnapshot(url) {
    return fetch(url).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    });
  }

  /* opts: { cacheKey, snapshotUrl, liveFetch(): Promise<data>, onData(data), onError(err) } */
  function load(opts) {
    var cached = readCache(opts.cacheKey);
    if (isFresh(cached)) {
      opts.onData(cached.data);
      return;
    }

    opts.liveFetch().then(function (data) {
      writeCache(opts.cacheKey, data);
      opts.onData(data);
    }).catch(function () {
      if (cached) {
        opts.onData(cached.data);
        return;
      }
      fetchSnapshot(opts.snapshotUrl).then(function (data) {
        opts.onData(data);
      }).catch(function (err) {
        opts.onError(err);
      });
    });
  }

  return { load: load, isFresh: isFresh, TTL_MS: TTL_MS };
})();

/* window global for the browser (unchanged runtime behaviour); CommonJS
   export alongside it purely so `bun test` can require() the pure helpers
   without a DOM — this branch never runs in the browser (module is
   undefined there). */
if (typeof window !== 'undefined') { window.DataCache = DataCache; }
if (typeof module !== 'undefined' && module.exports) { module.exports = DataCache; }
